import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { SEARCH_ADAPTER_DISPOSED, SearchAdapterError } from "../src/index";
import { CONFORMANCE_ASSERTIONS, runConformanceSuite } from "../src/testing";

const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")) as {
  exports: { "./testing": { types?: string; import?: string; require?: string } };
};

describe("adapter contracts scaffolding", () => {
  it("exports constants and errors", () => {
    expect(SEARCH_ADAPTER_DISPOSED).toBe("SEARCH_ADAPTER_DISPOSED");
    const err = new SearchAdapterError("X", "msg");
    expect(err.code).toBe("X");
  });

  it("exports the shared conformance harness", () => {
    expect(typeof runConformanceSuite).toBe("function");
    expect(CONFORMANCE_ASSERTIONS.length).toBeGreaterThan(0);
  });

  it("advertises the testing subpath as ESM-only", () => {
    expect(pkg.exports["./testing"].import).toBe("./dist/testing.js");
    expect(pkg.exports["./testing"].require).toBeUndefined();
  });
});
import { fileURLToPath } from "node:url";
import { defineConfig, type UserConfig } from "vitest/config";

const testingSource = fileURLToPath(new URL("./src/testing.ts", import.meta.url));

/** Workspace Vitest config so adapter tests resolve the harness source without a prior dist build. */
export function searchfnAdapterVitestConfig(overrides: UserConfig = {}): UserConfig {
  return defineConfig({
    ...overrides,
    resolve: {
      ...overrides.resolve,
      alias: {
        "@searchfn/adapter-contracts/testing": testingSource
      }
    },
    test: {
      globals: true,
      environment: "node",
      include: ["src/**/*.test.ts", "__tests__/**/*.test.ts"],
      ...overrides.test
    }
  });
}

export default searchfnAdapterVitestConfig();
{
  "name": "@searchfn/adapter-contracts",
  "version": "0.4.0",
  "description": "Shared adapter interfaces and error primitives for SearchFn adapters.",
  "license": "MIT",
  "type": "module",
  "main": "dist/index.cjs",
  "module": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "require": "./dist/index.cjs"
    },
    "./testing": {
      "types": "./dist/testing.d.ts",
      "import": "./dist/testing.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "node -e \"require('fs').rmSync('dist', { recursive: true, force: true })\" && tsup",
    "build:watch": "tsup --watch",
    "clean": "node -e \"require('fs').rmSync('dist', { recursive: true, force: true })\"",
    "test": "vitest run",
    "test:watch": "vitest watch",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@searchfn/core": "^0.3.0"
  },
  "peerDependencies": {
    "vitest": "^3.2.4"
  },
  "peerDependenciesMeta": {
    "vitest": {
      "optional": true
    }
  },
  "devDependencies": {
    "@types/node": "^24.9.1",
    "tsup": "^8.5.0",
    "typescript": "^5.9.3",
    "vitest": "^3.2.4"
  }
}

