- name: Post/Update PR comment
  # workflow_call sets github.event_name to "workflow_call", not "pull_request".
  # The caller payload is reused, so gate on PR number instead of event name.
  # workflow_dispatch inputs are strings, so accept boolean true or "true".
  # Fork PRs get a read-only token; skip mutation so gates still run.
  # Job summary is already written in the previous step.
  if: (inputs.post_pr_comment == true || inputs.post_pr_comment == 'true') && github.event.pull_request.number && github.event.pull_request.head.repo.full_name == github.repository
  continue-on-error: true
  uses: actions/github-script@v7
  with:
    script: |
      const fs = require('node:fs');
      const body = fs.readFileSync('ci-summary.md', 'utf8');
      const { owner, repo } = context.repo;
      const issue_number = context.payload.pull_request?.number;
      if (!issue_number) {
        core.info('No pull request number in event payload; skipping comment.');
        return;
      }
      const marker = '<!-- apifn-ci-report -->';

      const comments = await github.paginate(github.rest.issues.listComments, {
        owner,
        repo,
        issue_number,
        per_page: 100,
      });
      const existing = comments.find((c) => c.user?.type === 'Bot' && c.body?.includes(marker));

      if (existing) {
        await github.rest.issues.updateComment({ owner, repo, comment_id: existing.id, body });
      } else {
        await github.rest.issues.createComment({ owner, repo, issue_number, body });
      }

- name: Enforce CI gates
  shell: bash
  run: |
    set -euo pipefail

    validate_code="${{ steps.validate.outputs.exit_code }}"
    diff_code="${{ steps.diff.outputs.exit_code }}"
    test_code="${{ steps.test.outputs.exit_code }}"

    if [ -z "$diff_code" ]; then
      diff_code=0
    fi

    if [ "$validate_code" != "0" ]; then
      echo "Validation failed (exit=$validate_code)"
      exit "$validate_code"
    fi

    if [ "$diff_code" != "0" ]; then
      echo "Diff failed (exit=$diff_code)"
      exit "$diff_code"
    fi

    if [ "$test_code" != "0" ]; then
      echo "Collection tests failed (exit=$test_code)"
      exit "$test_code"
    fi

